mapper.select:
INSERT INTO practice_session (task_id)
SELECT task.id
FROM learning_task task
WHERE task.id = #{taskId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND task.status = 'STARTED'
RETURNING id

INSERT INTO practice_response (session_id, step_id, learner_text)
SELECT session.id,
       #{stepId, jdbcType=VARCHAR},
       #{learnerText, jdbcType=VARCHAR}
FROM practice_session session
JOIN learning_task task ON task.id = session.task_id
WHERE session.id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND session.status = 'IN_PROGRESS'
ON CONFLICT DO NOTHING
RETURNING submitted_at

SELECT response.session_id, response.step_id, response.learner_text, response.submitted_at
FROM practice_response response
JOIN practice_session session ON session.id = response.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE response.session_id = #{sessionId, jdbcType=OTHER}
  AND response.step_id = #{stepId, jdbcType=VARCHAR}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}

SELECT response.session_id, response.step_id, response.learner_text, response.submitted_at
FROM practice_response response
JOIN practice_session session ON session.id = response.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE response.session_id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
ORDER BY response.step_id

UPDATE practice_session AS session
SET status = 'COMPLETED',
    completed_at = CURRENT_TIMESTAMP
FROM learning_task task
WHERE session.id = #{sessionId, jdbcType=OTHER}
  AND task.id = session.task_id
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND session.status = 'IN_PROGRESS'
RETURNING session.completed_at

INSERT INTO deterministic_assessment (session_id, assessment_policy_version, duration_seconds)
SELECT session.id,
       #{assessmentPolicyVersion, jdbcType=VARCHAR},
       #{durationSeconds, jdbcType=BIGINT}
FROM practice_session session
JOIN learning_task task ON task.id = session.task_id
WHERE session.id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND session.status = 'COMPLETED'
RETURNING created_at

INSERT INTO deterministic_step_assessment (session_id, step_id, step_kind, outcome)
SELECT assessment.session_id,
       #{stepId, jdbcType=VARCHAR},
       #{stepKind, jdbcType=VARCHAR},
       #{outcome, jdbcType=VARCHAR}
FROM deterministic_assessment assessment
JOIN practice_session session ON session.id = assessment.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE assessment.session_id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
RETURNING session_id

SELECT assessment.session_id, assessment.assessment_policy_version,
       assessment.duration_seconds, assessment.created_at
FROM deterministic_assessment assessment
JOIN practice_session session ON session.id = assessment.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE assessment.session_id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}

SELECT step.step_id, step.step_kind, step.outcome
FROM deterministic_step_assessment step
JOIN deterministic_assessment assessment ON assessment.session_id = step.session_id
JOIN practice_session session ON session.id = assessment.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE step.session_id = #{sessionId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
ORDER BY step.step_id
